import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import API from '../api/axiosClient';

export default function WorkerDashboard({ orgId }) {
    const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

    // Fetch active pending charges ("in-progress" status for worker view)
    const { data: activePending = [] } = useQuery({
        queryKey: ['activePending', orgId],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/pending`);
            return res.data;
        },
        refetchInterval: 3000 // Poll every 3 seconds for live updates
    });

    // Fetch transactions grouped/filtered by Month & Year
    const { data: transactions = [] } = useQuery({
        queryKey: ['transactions', orgId, selectedMonth, selectedYear],
        queryFn: async () => {
            const res = await API.get(`/worker/${orgId}/transactions?month=${selectedMonth}&year=${selectedYear}`);
            return res.data;
        }
    });

    return (
        <div className="p-6 space-y-6">
            {/* Active In-Progress Charges Section */}
            <div className="bg-white p-4 rounded-xl shadow">
                <h3 className="font-bold text-lg mb-3">Awaiting Terminal Taps (In-Progress)</h3>
                {activePending.length === 0 ? (
                    <p className="text-gray-500 text-sm">No charges currently pending a card tap.</p>
                ) : (
                    <div className="space-y-2">
                        {activePending.map((item) => (
                            <div key={item.userId} className="flex justify-between items-center bg-amber-50 p-3 rounded border border-amber-200">
                                <div>
                                    <p className="font-medium">Amount: ${item.amount}</p>
                                    <p className="text-xs text-gray-500">Machine: {item.machineId}</p>
                                </div>
                                <span className="bg-amber-100 text-amber-800 text-xs px-2.5 py-1 rounded-full font-semibold animate-pulse">
                                    {item.status.toUpperCase()}
                                </span>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Monthly Filter & Transaction Ledger */}
            <div className="bg-white p-4 rounded-xl shadow">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg">Transaction Ledger</h3>
                    <div className="flex gap-2">
                        <select 
                            value={selectedMonth} 
                            onChange={(e) => setSelectedMonth(e.target.value)}
                            className="border p-2 rounded text-sm"
                        >
                            {Array.from({ length: 12 }, (_, i) => (
                                <option key={i + 1} value={i + 1}>
                                    {new Date(0, i).toLocaleString('default', { month: 'long' })}
                                </option>
                            ))}
                        </select>
                        <select 
                            value={selectedYear} 
                            onChange={(e) => setSelectedYear(e.target.value)}
                            className="border p-2 rounded text-sm"
                        >
                            <option value="2025">2025</option>
                            <option value="2026">2026</option>
                        </select>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b text-gray-600 text-sm">
                                <th className="p-2">Customer</th>
                                <th className="p-2">Type</th>
                                <th className="p-2">Amount</th>
                                <th className="p-2">Machine</th>
                                <th className="p-2">Date</th>
                            </tr>
                        </thead>
                        <tbody>
                            {transactions.map((tx) => (
                                <tr key={tx._id} className="border-b text-sm">
                                    <p className="p-2">{tx.userId?.name || 'Unknown'}</p>
                                    <td className="p-2">{tx.type}</td>
                                    <td className="p-2 font-medium">${tx.finalPaid}</td>
                                    <td className="p-2 text-gray-500">{tx.machineId}</td>
                                    <td className="p-2 text-gray-500">{new Date(tx.createdAt).toLocaleDateString()}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
